import { Component, createEffect, createMemo, createSignal, JSX } from "solid-js";

import { getMajorLeader, getPlayerDiplomacy } from "#core/ui/utilities/diplomacy-utilities.js";
import { getPlayerColorVariants } from "#core/ui/utilities/utilities-color.js";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

export interface PortraitIconData {
	playerId: PlayerId;
	size: number;
	desaturate?: boolean;
	class?: string;
}

export interface PortraitVictoryIconData extends PortraitIconData {
	isVictory: boolean;
	isDomination: boolean;
}

function desaturateOnCondition(condition: boolean, existingProps: JSX.CSSProperties) {
	if (condition) {
		existingProps.filter = "saturate(0)";
	}
	return existingProps;
}

export interface LeaderIconProps {
	icon: string;
	size: number;
	desaturate?: boolean;
}
export const LeaderIconComponent: Component<LeaderIconProps> = (props) => {
	const style = createMemo(() =>
		desaturateOnCondition(props.desaturate ?? false, { "background-image": props.icon }),
	);
	return (
		<div
			class={`bg-center bg-no-repeat bg-contain size-${props.size} -mt-1 pointer-events-auto`}
			style={style()}
		/>
	);
};

const PortraitIconComponent: Component<PortraitIconData> = (props) => {
	const [iconProps, setIconProps] = createSignal<LeaderIconProps>();
	const [backgroundColor, setBackgroundColor] = createSignal<string>("");
	createEffect(() => {
		if (props.playerId === PlayerIds.NO_PLAYER) {
			return;
		}

		const majorLeader = getMajorLeader(props.playerId);

		if (!majorLeader) {
			return;
		}
		const leaderType = GameInfo.Leaders.lookup(majorLeader.leaderType)?.LeaderType;

		const playerDiplomacy = getPlayerDiplomacy(majorLeader);
		if (!playerDiplomacy) {
			return;
		}

		let portraitContext = "";
		switch (playerDiplomacy.getRelationshipEnum(GameContext.localObserverID)) {
			case DiplomacyPlayerRelationships.PLAYER_RELATIONSHIP_HOSTILE:
			case DiplomacyPlayerRelationships.PLAYER_RELATIONSHIP_UNFRIENDLY:
				portraitContext = "LEADER_ANGRY";
				break;
			case DiplomacyPlayerRelationships.PLAYER_RELATIONSHIP_FRIENDLY:
			case DiplomacyPlayerRelationships.PLAYER_RELATIONSHIP_HELPFUL:
				portraitContext = "LEADER_HAPPY";
				break;
			default:
				break;
		}

		setIconProps({
			icon: UI.getIconCSS(leaderType ?? "UNKNOWN_LEADER", portraitContext),
			size: props.size,
			desaturate: props.desaturate,
		});

		const variants = getPlayerColorVariants(props.playerId);
		if (variants) {
			setBackgroundColor(variants.secondaryColor.mainColor);
		}
	});

	return (
		<div
			class={`portrait-icon-container relative bg-center bg-no-repeat bg-contain size-${props.size} ${props.class ?? ""}`}
			style={desaturateOnCondition(props.desaturate ?? false, {
				"background-image": "url(blp:final_leader-hex)",
				"fxs-background-image-tint": backgroundColor(),
			})}
			data-name="Portrait-Icon"
		>
			<div
				class={`portrait-icon__background bg-center bg-no-repeat bg-contain size-${props.size}`}
				style={{
					"background-image": "url(blp:hud_diplo_hex-frame)",
				}}
			>
				{iconProps() !== undefined && <LeaderIconComponent {...iconProps()!} />}
			</div>
		</div>
	);
};

export const PortraitIcon = ComponentRegistry.register({
	name: "PortraitIcon",
	createInstance: PortraitIconComponent,
});
